<script setup>
import {computed,ref,onMounted} from 'vue'
import TagInput from './TagInput.vue'
import {unwrap,errorText,dateTime} from './utils'
const props=defineProps({api:Object,pluginId:{type:String,default:'HitAndRun'}})
const emit=defineEmits(['action'])
const data=ref(null),busy=ref(false),error=ref(''),info=ref(''),mode=ref('tasks'),selected=ref(''),tab=ref('policy'),recordTab=ref('runs'),search=ref('')
const editor=ref(false),editKind=ref('tasks'),edit=ref({}),form=ref(null),removeOpen=ref(false),dragged=ref('')
const clone=x=>JSON.parse(JSON.stringify(x)),base=()=>`plugin/${props.pluginId}`
const items=computed(()=>data.value?.config[mode.value]||[])
const keyOf=x=>String(mode.value==='tasks'?x.id:x.site_id)
const current=computed(()=>items.value.find(x=>keyOf(x)===selected.value))
const siteName=id=>data.value?.options.sites.find(s=>s.value===id)?.title||`站点 ${id}`
const title=x=>mode.value==='tasks'?x.name:siteName(x.site_id)
const detectionItems=[{title:'读取下载事件标记，未知则保护',value:'marked'},{title:'本站全部按 H&R',value:'all'},{title:'本站无 H&R，额外标签仍生效',value:'none'}]
const basisItems=[{title:'下载器分享率',value:'client'},{title:'上传量／完整种子体积',value:'full_size'}]
const detectionName=v=>detectionItems.find(x=>x.value===v)?.title||v
const targets=s=>[s.seed_hours>0?`做种 ≥ ${s.seed_hours} 小时`:'',s.ratio>0?`${s.ratio_basis==='full_size'?'上传量／完整体积':'分享率'} ≥ ${s.ratio}`:''].filter(Boolean).join(' 或 ')
const records=computed(()=>(data.value?.records||[]).filter(r=>current.value&&(!r.history_exempt||r.owned?.length)&&
  (mode.value==='tasks'?r.downloader===current.value.downloader:r.site_ids?.includes(current.value.site_id))&&
  (!search.value||`${r.name} ${r.hash}`.toLowerCase().includes(search.value.toLowerCase()))).sort((a,b)=>(b.checked_at||0)-(a.checked_at||0)))
const runs=computed(()=>(data.value?.runs||[]).flatMap(run=>(run.tasks||[]).filter(t=>current.value&&(mode.value==='tasks'?t.task_id===current.value.id:t.details?.some(d=>d.site_ids?.includes(current.value.site_id)))).map(t=>({...t,started_at:run.started_at,finished_at:run.finished_at,details:mode.value==='sites'?t.details.filter(d=>d.site_ids?.includes(current.value.site_id)):t.details}))))
const stateName=r=>r.error?'更新失败':r.absent?'已不在下载器':({protected:'保护中',unknown:'待确认',released:'已达标',clear:'非 H&R'})[r.state]||'待检查'
const protectedCount=computed(()=>records.value.filter(r=>r.owned?.length).length)
const availableSites=computed(()=>(data.value?.options.sites||[]).filter(s=>s.value===edit.value.site_id||!data.value.config.sites.some(r=>r.site_id===s.value)))
const effectiveSites=computed(()=>(data.value?.config.sites||[]).filter(s=>current.value?.site_ids==null||current.value.site_ids.includes(s.site_id)))
const scopeItems=computed(()=>(data.value?.options.sites||[]))
const required=v=>!!String(v??'').trim()||'请填写此项'
async function load(){try{data.value=unwrap(await props.api.get(`${base()}/status`));if(!current.value)selected.value=items.value.length?keyOf(items.value[0]):''}catch(e){error.value=errorText(e)}}
function select(item){selected.value=keyOf(item);tab.value='policy';search.value=''}
function switchMode(value){mode.value=value;selected.value=items.value.length?keyOf(items.value[0]):'';tab.value='policy';search.value=''}
function openEditor(kind,value){editKind.value=kind;error.value='';edit.value=clone(value||(kind==='tasks'?{id:crypto.randomUUID(),name:'标签扫描',enabled:true,downloader:'',cron:'7,22,37,52 * * * *',extra_tags:[],fallback_hours:168,remove_extra_tags:false,site_ids:null}:kind==='sites'?{site_id:null,detection:'marked',tracker_hosts:[],seed_hours:168,ratio:0,ratio_basis:'client'}:{confirmed_tag:data.value.config.confirmed_tag,pending_tag:data.value.config.pending_tag}));editor.value=true}
async function persist(config){busy.value=true;error.value='';try{unwrap(await props.api.post(`${base()}/settings`,config));emit('action');await load();return true}catch(e){error.value=errorText(e);return false}finally{busy.value=false}}
async function save(){if(!(await form.value?.validate())?.valid)return;const cfg=clone(data.value.config),kind=editKind.value;if(kind==='labels')Object.assign(cfg,edit.value);else{const field=kind==='tasks'?'id':'site_id';const index=cfg[kind].findIndex(x=>x[field]===edit.value[field]);if(index<0)cfg[kind].push(clone(edit.value));else cfg[kind][index]=clone(edit.value)}if(await persist(cfg)){editor.value=false;info.value='已保存';if(kind!=='labels'){mode.value=kind;selected.value=String(edit.value[kind==='tasks'?'id':'site_id'])}}}
async function remove(){const cfg=clone(data.value.config);cfg[mode.value]=cfg[mode.value].filter(x=>keyOf(x)!==selected.value);if(await persist(cfg)){removeOpen.value=false;info.value='已移除配置，已有保护标签保留'}}
async function reorder(from,to){if(busy.value||from===to)return;const cfg=clone(data.value.config),list=cfg[mode.value],a=list.findIndex(x=>keyOf(x)===from),b=list.findIndex(x=>keyOf(x)===to);if(a<0||b<0)return;list.splice(b,0,list.splice(a,1)[0]);await persist(cfg)}
function move(index,delta){const other=items.value[index+delta];if(other)reorder(keyOf(items.value[index]),keyOf(other))}
async function scan(){busy.value=true;error.value='';try{unwrap(await props.api.post(`${base()}/scan`,{task_id:current.value.id}));info.value='当前任务已排队，仅检查和更新标签';tab.value='records';recordTab.value='runs'}catch(e){error.value=errorText(e)}finally{busy.value=false}}
onMounted(load)
</script>
<template><div class="hr-workbench">
<header class="toolbar"><div><h2>H&R助手</h2><p class="muted">识别 H&R · 标签保护 · 达标解除</p></div><div class="actions"><VBtn icon="mdi-refresh" variant="text" aria-label="刷新" :disabled="busy" @click="load"/><VBtn variant="tonal" prepend-icon="mdi-tag-outline" :disabled="!data||busy" @click="openEditor('labels')">保护标签</VBtn></div></header>
<VAlert v-if="error" type="error" class="mb-4" closable @click:close="error=''">{{error}}</VAlert><VAlert v-if="info" type="success" variant="tonal" class="mb-4" closable @click:close="info=''">{{info}}</VAlert>
<div v-if="data" class="hr-layout">
<aside class="task-rail"><VSelect :model-value="mode" :items="[{title:'下载器任务',value:'tasks'},{title:'站点规则',value:'sites'}]" label="查看内容" hide-details density="compact" class="mb-3" @update:model-value="switchMode"/>
<div v-for="(item,index) in items" :key="keyOf(item)" class="task-card" :class="{active:keyOf(item)===selected}" role="button" tabindex="0" :draggable="!busy" @click="select(item)" @keydown.enter.self="select(item)" @keydown.space.self.prevent="select(item)" @dragstart="dragged=keyOf(item)" @dragover.prevent @drop.prevent="reorder(dragged,keyOf(item));dragged=''">
<div class="task-heading"><VIcon icon="mdi-drag-vertical" size="18" class="muted"/><strong :title="title(item)">{{title(item)}}</strong><VChip v-if="mode==='tasks'" size="x-small" :color="item.enabled?'success':'default'">{{item.enabled?'启用':'停用'}}</VChip></div>
<template v-if="mode==='tasks'"><div class="rail-tags"><span class="rail-pill rail-accent">{{item.downloader}}</span><span class="rail-pill rail-neutral">监听与扫描</span></div><div class="rail-details"><div class="rail-row"><span class="rail-pill rail-label">生效站点</span><span class="rail-pill" :title="item.site_ids==null?'全部站点':item.site_ids.map(siteName).join('、')||'未选择'">{{item.site_ids==null?'全部站点':item.site_ids.map(siteName).join('、')||'未选择'}}</span></div><div class="rail-row"><span class="rail-pill rail-label">额外标签</span><span class="rail-pill" :title="item.extra_tags.join('、')||'无'">{{item.extra_tags.join('、')||'无'}}</span></div><div class="rail-row"><span class="rail-pill rail-label">执行周期</span><span class="rail-pill">{{item.cron}}</span></div></div></template><template v-else><div class="rail-tags"><span class="rail-pill rail-accent">站点规则</span><span class="rail-pill rail-neutral">全局共享</span></div><div class="rail-details"><div class="rail-row"><span class="rail-pill rail-label">识别方式</span><span class="rail-pill" :title="detectionName(item.detection)">{{detectionName(item.detection)}}</span></div><div class="rail-row"><span class="rail-pill rail-label">解除条件</span><span class="rail-pill" :title="targets(item)">{{targets(item)}}</span></div></div></template>
<div class="card-bottom"><span/><div><VBtn icon="mdi-arrow-up" size="x-small" variant="text" aria-label="上移任务" :disabled="busy||index===0" @click.stop="move(index,-1)"/><VBtn icon="mdi-arrow-down" size="x-small" variant="text" aria-label="下移任务" :disabled="busy||index===items.length-1" @click.stop="move(index,1)"/><VBtn icon="mdi-pencil" size="x-small" variant="text" aria-label="编辑卡片" :disabled="busy" @click.stop="openEditor(mode,item)"/></div></div>
</div><VBtn block variant="tonal" color="primary" prepend-icon="mdi-plus" :disabled="busy" @click="openEditor(mode)">{{mode==='tasks'?'新建任务':'新增站点规则'}}</VBtn>
</aside>
<main class="workspace"><template v-if="current"><div class="detail-heading"><div><h3>{{title(current)}}</h3><p class="muted">{{mode==='tasks'?current.downloader:'全局共享，按种子关联站点匹配'}}</p></div><div class="actions"><VBtn v-if="mode==='tasks'" color="primary" variant="tonal" :loading="busy" :disabled="!current.enabled" @click="scan">检查标签</VBtn><VBtn icon="mdi-pencil" variant="text" aria-label="编辑当前策略" :disabled="busy" @click="openEditor(mode,current)"/><VBtn icon="mdi-delete-outline" variant="text" aria-label="移除当前配置" :disabled="busy" @click="removeOpen=true"/></div></div>
<VTabs v-model="tab" class="mb-5"><VTab value="policy">策略</VTab><VTab value="records">执行记录</VTab></VTabs>
<div v-if="tab==='policy'" class="policy-body">
<template v-if="mode==='tasks'"><div class="summary-grid"><div><span>事件识别与扫描</span><strong>{{current.enabled?'启用':'停用'}}</strong></div><div><span>扫描周期</span><strong class="cron">{{current.cron}}</strong></div><div><span>未知站点做种目标</span><strong>{{current.fallback_hours}} 小时</strong></div></div>
<section class="policy-card"><h4>标签处理</h4><div class="tag-line"><span>确认／按 H&R 对待</span><VChip size="small">{{data.config.confirmed_tag}}</VChip></div><div class="tag-line"><span>无法明确识别</span><VChip size="small">{{data.config.pending_tag}}</VChip></div><div class="tag-line"><span>额外按 H&R 对待</span><VChip v-for="label in current.extra_tags" :key="label" size="small">{{label}}</VChip><span v-if="!current.extra_tags.length" class="muted">无</span></div><p class="muted">命中任一额外标签即纳管，达标后移除助手添加的 H&R 标签{{current.remove_extra_tags?'及额外标签':'，保留额外标签'}}。</p></section>
<section class="policy-card"><div class="section-heading"><h4>生效站点</h4><VBtn variant="text" size="small" @click="switchMode('sites')">管理站点规则</VBtn></div><p class="muted mb-3">{{current.site_ids==null?'全部站点（含后续新增），未识别站点按未知站点目标处理':'仅处理所选站点，未识别站点跳过'}}。多个关联站点须分别达标</p><div class="tag-line mb-3"><VChip v-for="sid in (current.site_ids||[])" :key="sid" size="small">{{siteName(sid)}}</VChip></div><p v-if="current.site_ids?.length===0" class="muted">未选择站点，本任务不处理种子</p><div class="site-grid"><button v-for="site in effectiveSites" :key="site.site_id" class="site-summary" @click="switchMode('sites');selected=String(site.site_id)"><strong>{{siteName(site.site_id)}}</strong><span class="muted">{{detectionName(site.detection)}}</span><span>{{targets(site)}}</span><span class="muted small">查看规则 →</span></button></div></section>
<p class="muted small">监听新下载并定时扫描，历史种子仅在命中额外标签时纳管，停用后保留已有标签。</p></template>
<template v-else><section class="policy-card"><h4>识别规则</h4><p>{{detectionName(current.detection)}}</p><div class="tag-line"><span class="muted">Tracker 域名</span><VChip v-for="host in current.tracker_hosts" :key="host" size="small">{{host}}</VChip><span v-if="!current.tracker_hosts.length" class="muted">使用站点域名匹配</span></div></section><section class="policy-card"><h4>解除标签条件</h4><p class="release-rule">下载完成 <b>且</b>（{{targets(current)}}）</p><p class="muted">填写含余量的最终目标，时间与分享指标为或，多个关联站点为且，待确认种子同样适用。</p><p class="muted small">按下载器数据估算，达标后下一次扫描解除，不代表站点账户已确认达标</p></section><section class="policy-card"><h4>使用范围</h4><p>选择了本站的下载器任务共享此规则，按种子关联站点匹配</p></section></template>
</div>
<div v-else class="records-card"><div class="records-toolbar"><VBtnToggle v-model="recordTab" mandatory variant="outlined" density="compact"><VBtn value="runs">扫描记录</VBtn><VBtn value="seeds">种子状态</VBtn></VBtnToggle><span class="muted small">当前范围 {{records.length}} 个种子 · {{protectedCount}} 个带自有保护标签</span></div>
<template v-if="recordTab==='runs'"><p class="muted small mb-3">{{mode==='sites'?'仅显示涉及本站标签变化的扫描':'仅显示当前下载器任务的扫描'}}，最多保留最近 100 轮</p><VExpansionPanels v-if="runs.length" variant="accordion"><VExpansionPanel v-for="(run,i) in runs" :key="`${run.started_at}-${i}`"><VExpansionPanelTitle><div class="run-heading"><span>{{dateTime(run.finished_at||run.started_at)}}</span><VChip size="small" :color="run.failed?'warning':'success'">{{run.failed?'有失败':'完成'}}</VChip><span class="muted">检查 {{run.checked}} · 更新 {{run.changed}} · 失败 {{run.failed}}</span></div></VExpansionPanelTitle><VExpansionPanelText><VAlert v-if="run.error" type="warning" variant="tonal" class="mb-3">{{run.error}}</VAlert><div v-for="detail in run.details" :key="detail.hash" class="change-row"><strong>{{detail.name}}</strong><div class="tag-line"><VChip v-for="label in detail.added" :key="'add'+label" size="small" color="primary">添加 {{label}}</VChip><VChip v-for="label in detail.removed" :key="'remove'+label" size="small" color="success">移除 {{label}}</VChip></div><p class="muted">{{detail.error||detail.reason}}</p></div><p v-if="!run.details?.length" class="muted">本轮无标签变化</p></VExpansionPanelText></VExpansionPanel></VExpansionPanels><div v-else class="empty">暂无扫描记录，可查看现有种子状态</div></template>
<template v-else><VTextField v-model="search" prepend-inner-icon="mdi-magnify" label="搜索名称或 Hash" hide-details density="compact" class="mb-4"/><VDataTable :items="records" :headers="[{title:'种子',key:'name'},{title:'状态',key:'state'},{title:'做种小时',key:'seed_hours'},{title:'保护标签',key:'owned'},{title:'最近检查',key:'checked_at'}]" :items-per-page="10"><template #item.name="{item}"><div class="record-name">{{item.name}}</div><div class="muted small">{{item.downloader}}</div><div class="muted small">{{item.error||item.reason}}</div></template><template #item.state="{item}"><VChip size="small" :color="item.error?'warning':item.state==='released'?'success':'default'">{{stateName(item)}}</VChip></template><template #item.owned="{item}"><div class="tag-line"><VChip v-for="label in item.owned" :key="label" size="small">{{label}}</VChip></div></template><template #item.checked_at="{item}">{{dateTime(item.checked_at)}}</template></VDataTable></template></div>
</template><div v-else class="empty">从左侧新建{{mode==='tasks'?'下载器任务':'站点规则'}}</div></main>
</div>
<VDialog v-model="editor" max-width="860" scrollable><VCard><VToolbar color="transparent"><VToolbarTitle>{{editKind==='labels'?'保护标签':editKind==='tasks'?'下载器任务':'站点规则'}}</VToolbarTitle><VSpacer/><VBtn icon="mdi-close" aria-label="关闭编辑器" @click="editor=false"/></VToolbar><VCardText class="editor-body"><VAlert v-if="error" type="error" class="mb-4">{{error}}</VAlert><VForm ref="form" @submit.prevent="save"><div class="form-grid">
<template v-if="editKind==='tasks'"><VTextField v-model="edit.name" label="任务名称" :rules="[required]"/><VSelect v-model="edit.downloader" :items="data?.options.downloaders" label="下载器" :rules="[required]"/><VSwitch class="wide" :model-value="edit.site_ids==null" @update:model-value="edit.site_ids=$event?null:scopeItems.map(s=>s.value)" label="全部站点" hint="包含后续新增站点，未识别站点使用未知站点目标" persistent-hint color="primary" inset/><VSelect v-if="edit.site_ids!=null" class="wide" v-model="edit.site_ids" :items="scopeItems" label="生效站点" multiple chips closable-chips hint="任一关联站点命中即纳管，解除须所有关联站点分别达标。未选中或未识别时跳过，已有标签保留" persistent-hint/><VTextField v-model="edit.cron" label="扫描 Cron" :rules="[required]"/><VTextField v-model.number="edit.fallback_hours" type="number" min="1" label="未知站点做种目标（小时）"/><TagInput class="wide" :model-value="edit.extra_tags.join(',')" @update:model-value="edit.extra_tags=$event.split(',').filter(Boolean)" label="额外按 H&R 对待的标签" hint="回车添加，逗号分隔，任意命中即纳管" persistent-hint/><VSwitch class="wide" v-model="edit.remove_extra_tags" label="达标后同时移除额外标签" hint="如辅种，关闭则保留额外标签，只移除助手添加的 H&R 标签" persistent-hint color="primary" inset/><VSwitch class="wide" v-model="edit.enabled" label="启用任务" hint="控制该下载器的下载事件识别和定时扫描，停用后已有标签保留" persistent-hint color="primary" inset/></template>
<template v-else-if="editKind==='sites'"><VSelect class="wide" v-model="edit.site_id" :items="availableSites" label="已保存的站点" :rules="[required]" :disabled="data?.config.sites.some(s=>s.site_id===edit.site_id)"/><VSelect class="wide" v-model="edit.detection" :items="detectionItems" label="识别方式"/><VCombobox class="wide" v-model="edit.tracker_hosts" label="额外 Tracker 域名" multiple chips closable-chips/><VTextField v-model.number="edit.seed_hours" type="number" min="0" label="累计做种目标（小时）" hint="最终值，含余量，0 关闭" persistent-hint/><VTextField v-model.number="edit.ratio" type="number" min="0" label="分享指标目标" hint="与时长为或，0 关闭，至少启用一项" persistent-hint/><VSelect class="wide" v-model="edit.ratio_basis" :items="basisItems" label="分享指标口径"/><VAlert class="wide" variant="tonal" type="info">下载完成 且（{{targets(edit)||'请设置时长或分享指标'}}），多个关联站点须分别满足。</VAlert></template>
<template v-else><VTextField v-model="edit.confirmed_tag" label="确认 H&R／按 H&R 对待" :rules="[required]" hide-details="auto"/><VTextField v-model="edit.pending_tag" label="无法明确识别" :rules="[required]" hide-details="auto"/><p class="wide text-caption muted">刷流和选用 H&R 标签的清理任务跟随标签改名，扫描时迁移助手添加的标签，人工标签保留。</p></template>
</div></VForm></VCardText><VCardActions><VSpacer/><VBtn @click="editor=false">取消</VBtn><VBtn color="primary" :loading="busy" @click="save">保存</VBtn></VCardActions></VCard></VDialog>
<VDialog v-model="removeOpen" max-width="480"><VCard title="移除配置"><VCardText>移除“{{current?title(current):''}}”的配置，已有标签保留。{{mode==='sites'?'失去映射的种子将按下载器任务中的未知站点目标处理。':''}}</VCardText><VCardActions><VSpacer/><VBtn @click="removeOpen=false">取消</VBtn><VBtn color="error" :loading="busy" @click="remove">移除</VBtn></VCardActions></VCard></VDialog>
